sql.if:
AND (
    coalesce(k.owner_user_id, k.create_user_id) = #{accessUserId}
    OR k.visibility = 'ORG'
    OR (
        coalesce(k.visibility, 'PRIVATE') = 'DEPT'
        AND k.dept_id IS NOT NULL
        AND #{accessDeptId} IS NOT NULL
        AND k.dept_id = #{accessDeptId}
    )
    OR EXISTS (
        select 1 from kb_acl_member m
         where m.kb_id = k.kb_id
           and m.user_id = #{accessUserId}
           and upper(trim(m.role)) in ('VIEWER', 'EDITOR', 'QUALITY', 'OWNER')
    )
)
AND NOT (
    coalesce(k.owner_user_id, k.create_user_id) IS NULL
    AND k.dept_id IS NULL
    AND (k.visibility IS NULL OR k.visibility = 'PRIVATE' OR k.visibility = 'MEMBERS')
)

mapper.select:


    del_flag = '0'

        AND kb_name like concat('%', #{kbName}, '%')


        AND status = #{status}


        AND dept_id = #{deptId}


        AND (
            coalesce(owner_user_id, create_user_id) = #{accessUserId}
            OR visibility = 'ORG'
            OR (
                coalesce(visibility, 'PRIVATE') = 'DEPT'
                AND dept_id IS NOT NULL
                AND #{accessDeptId} IS NOT NULL
                AND dept_id = #{accessDeptId}
            )
            OR EXISTS (
                select 1 from kb_acl_member m
                 where m.kb_id = kb_knowledge.kb_id
                   and m.user_id = #{accessUserId}
                   and upper(trim(m.role)) in ('VIEWER', 'EDITOR', 'QUALITY', 'OWNER')
            )
        )
        AND NOT (
            coalesce(owner_user_id, create_user_id) IS NULL
            AND dept_id IS NULL
            AND (visibility IS NULL OR visibility = 'PRIVATE' OR visibility = 'MEMBERS')
        )


order by kb_id desc

select k.kb_id, k.kb_name, k.description, k.status, k.create_user_id, k.owner_user_id, k.visibility, k.dept_id, k.create_by, k.create_time, k.update_time, coalesce(d.doc_count, 0) as doc_count, coalesce(d.processing_count, 0) as processing_count, coalesce(d.failed_count, 0) as failed_count, coalesce(d.ready_count, 0) as ready_count, d.last_content_time from kb_knowledge k left join ( select kb_id, count(*) as doc_count, count(*) filter (where parse_status in ('PENDING','PARSING','CHUNKING','EMBEDDING','PROCESSING')) as processing_count, count(*) filter (where parse_status = 'FAILED') as failed_count, count(*) filter (where parse_status = 'COMPLETED') as ready_count, max(coalesce(update_time, create_time)) as last_content_time from kb_document where del_flag = '0' group by kb_id ) d on d.kb_id = k.kb_id
k.del_flag = '0'
AND k.kb_id = #{kbId}
AND (k.kb_name like concat('%', #{kbName}, '%') OR coalesce(k.description,'') like concat('%', #{kbName}, '%') OR coalesce(k.create_by,'') like concat('%', #{kbName}, '%'))
AND k.status = #{status}
order by coalesce(d.last_content_time, k.update_time, k.create_time) desc nulls last, k.kb_id desc

mapper.update:
update kb_knowledge
kb_name = #{kbName}, description = #{description}, embedding_model_code = #{embeddingModelCode}, graph_enabled = #{graphEnabled}, extract_model_code = #{extractModelCode}, chunk_strategy = #{chunkStrategy}, chunk_size = #{chunkSize}, chunk_overlap = #{chunkOverlap}, status = #{status}, owner_user_id = #{ownerUserId}, visibility = #{visibility}, remark = #{remark}, update_by = #{updateBy}, update_time = now()
where kb_id = #{kbId}
